import type { LucideIcon } from 'lucide-react';
import {
    Settings,
    ChevronDown,
    ChevronRight,
    ClipboardCheck,
    User,
    Archive,
    Activity,
    Image,
    Upload,
} from 'lucide-react';
import { useState, useEffect } from 'react';
import type { FC } from 'react';
import { Link, useLocation } from 'react-router-dom';
import iconNike from '@/assets/images/nike-filled.svg';

type Menu = {
    label: string;
    icon: LucideIcon;
    key: string;
    link: string;
    children: Menu[];
};

const menus: Menu[] = [
    {
        label: 'Asset',
        icon: Image,
        key: 'assets',
        link: '/assets/list', // Direct link to asset list
        children: [], // No children for direct link
    },
    {
        label: 'Ingestion',
        icon: Upload,
        key: 'ingestion',
        link: '/ingestion/list', // Direct link to ingestion list
        children: [], // No children for direct link
    },
    {
        label: 'Task',
        icon: ClipboardCheck,
        key: 'task',
        link: '/task/list', // Direct link to tasks list
        children: [], // No children for direct link
    },
    {
        label: 'Distribution',
        icon: Archive,
        key: 'distribution',
        link: '/distribution/list', // Direct link to distribution list
        children: [], // No children for direct link
    },
    {
        label: 'Tracking List',
        icon: Activity,
        key: 'tracking',
        link: '/tracking/list', // Already correctly linked
        children: [],
    },
    {
        label: 'Administration',
        icon: Settings,
        key: 'administration',
        link: '/administration',
        children: [
            { label: 'Users', icon: User, key: 'users', link: '/administration/users', children: [] },
        ],
    },
];

const AppAsider: FC = () => {
    const location = useLocation();
    const [openMenu, setOpenMenu] = useState<string | null>(null);
    const [activeMenu, setActiveMenu] = useState<string>('assets'); // Default to assets
    const [activeSubmenu, setActiveSubmenu] = useState<string | null>(null);

    // Toggle submenu display status
    const toggleSubMenu = (menuKey: string) => {
        setOpenMenu(openMenu === menuKey ? null : menuKey);
    };

    // Set active menu based on current location
    useEffect(() => {
        const path = location.pathname;

        // Check for direct menu matches
        for (const menu of menus) {
            if (menu.children.length === 0) {
                // For direct menus, check if path starts with the menu's path base
                const basePath = menu.link.split('/').slice(0, 2).join('/');
                if (path === menu.link || path.startsWith(basePath + '/')) {
                    setActiveMenu(menu.key);
                    setActiveSubmenu(null);
                    return;
                }
            } else {
                // For menus with submenus
                for (const submenu of menu.children) {
                    if (path === submenu.link || path.startsWith(submenu.link + '/')) {
                        setActiveMenu(menu.key);
                        setActiveSubmenu(submenu.key);
                        // Automatically open the parent menu
                        setOpenMenu(menu.key);
                        return;
                    }
                }

                // Check if path matches parent menu
                if (path === menu.link || path.startsWith(menu.link + '/')) {
                    setActiveMenu(menu.key);
                    setActiveSubmenu(null);
                    return;
                }
            }
        }

        // Default to assets if no match found
        if (path === '/' || !activeMenu) {
            setActiveMenu('assets');
            setActiveSubmenu(null);
        }
    }, [location.pathname]);

    return (
        <>
            <div className="group absolute top-0 left-0 z-10 h-full min-h-screen w-20 overflow-x-hidden overflow-y-auto bg-[#0D1117] transition-all duration-300 hover:w-56">
                {/* Logo area */}
                <div className="flex items-center justify-center pt-6 pb-4">
                    <img src={iconNike} alt="Logo" className="mb-2 size-12 invert filter" />
                    <span className="ml-2 hidden text-base font-bold whitespace-nowrap text-white opacity-0 transition-opacity duration-300 group-hover:block group-hover:opacity-100">GC CONTENT HUB</span>
                </div>

                {/* Navigation menu */}
                <nav className="mt-4">
                    <ul className="space-y-1">
                        {menus.map((menu) => {
                            const isActive = activeMenu === menu.key;

                            return (
                                <li key={menu.key} className="flex flex-col items-center">
                                    {menu.children.length === 0 ? (
                                        // Direct link menu item
                                        <Link
                                            to={menu.link}
                                            className={`relative flex w-full items-center justify-center rounded px-4 py-2.5 group-hover:justify-start hover:bg-[#1C2533] ${isActive ? 'text-white' : 'text-gray-300'}`}
                                            onClick={() => {
                                                setActiveMenu(menu.key);
                                                setActiveSubmenu(null);
                                            }}
                                        >
                                            {/* White circle background for collapsed state only */}
                                            {isActive && (
                                                <div className="absolute top-1/2 left-1/2 h-7 w-7 -translate-x-1/2 -translate-y-1/2 rounded-full bg-white group-hover:opacity-0" />
                                            )}

                                            {/* Menu icon - with persistent highlighting */}
                                            <div className="absolute left-1/2 z-10 -translate-x-1/2 transition-all duration-300 group-hover:left-4 group-hover:translate-x-0">
                                                <menu.icon className={`size-5 ${
                                                    isActive
                                                        ? 'text-[#0D1117] group-hover:text-white' // Black in collapsed, white in expanded
                                                        : 'text-gray-300'
                                                }`}
                                                />
                                            </div>

                                            {/* Menu label */}
                                            <span className={`ml-9 font-medium whitespace-nowrap opacity-0 transition-opacity duration-300 group-hover:opacity-100 ${
                                                isActive ? 'text-white' : 'text-gray-300'
                                            }`}
                                            >
                                                {menu.label}
                                            </span>
                                        </Link>
                                    ) : (
                                        // Menu with submenu
                                        <>
                                            <button
                                                onClick={() => toggleSubMenu(menu.key)}
                                                className={`relative flex w-full items-center justify-center rounded px-4 py-2.5 group-hover:justify-start hover:bg-[#1C2533] ${isActive ? 'text-white' : 'text-gray-300'}`}
                                            >
                                                {/* White circle background for collapsed state only */}
                                                {isActive && (
                                                    <div className="absolute top-1/2 left-1/2 h-7 w-7 -translate-x-1/2 -translate-y-1/2 rounded-full bg-white group-hover:opacity-0" />
                                                )}

                                                {/* Menu icon - with persistent highlighting */}
                                                <div className="absolute left-1/2 z-10 -translate-x-1/2 transition-all duration-300 group-hover:left-4 group-hover:translate-x-0">
                                                    <menu.icon className={`size-5 ${
                                                        isActive
                                                            ? 'text-[#0D1117] group-hover:text-white' // Black in collapsed, white in expanded
                                                            : 'text-gray-300'
                                                    }`}
                                                    />
                                                </div>

                                                {/* Menu label */}
                                                <span className={`ml-9 font-medium whitespace-nowrap opacity-0 transition-opacity duration-300 group-hover:opacity-100 ${
                                                    isActive ? 'text-white' : 'text-gray-300'
                                                }`}
                                                >
                                                    {menu.label}
                                                </span>

                                                {/* Expand/collapse indicator */}
                                                <span className="absolute right-2 opacity-0 transition-opacity duration-300 group-hover:opacity-100">
                                                    {openMenu === menu.key
                                                        ? (
                                                                <ChevronDown className={`size-4 ${isActive ? 'text-white' : 'text-gray-300'}`} />
                                                            )
                                                        : (
                                                                <ChevronRight className={`size-4 ${isActive ? 'text-white' : 'text-gray-300'}`} />
                                                            )}
                                                </span>
                                            </button>

                                            {/* Submenu */}
                                            {openMenu === menu.key && menu.children.length > 0 && (
                                                <ul className="mt-1 hidden w-full bg-[#161B22] transition-all duration-300 group-hover:block">
                                                    {menu.children.map((subMenu) => {
                                                        const isSubActive = activeSubmenu === subMenu.key;

                                                        return (
                                                            <li key={`${menu.key}-${subMenu.key}`} className="flex justify-start py-0.5 pl-[34px]">
                                                                <Link
                                                                    to={subMenu.link}
                                                                    className={`flex w-full items-center gap-2 rounded px-3 py-1.5 text-sm ${
                                                                        isSubActive
                                                                            ? 'bg-white text-[#0D1117]'
                                                                            : 'text-gray-300 hover:bg-[#1C2533]'
                                                                    }`}
                                                                    onClick={() => {
                                                                        setActiveMenu(menu.key);
                                                                        setActiveSubmenu(subMenu.key);
                                                                    }}
                                                                >
                                                                    <subMenu.icon className={`size-4 flex-shrink-0 ${
                                                                        isSubActive ? 'text-[#0D1117]' : 'text-gray-400'
                                                                    }`}
                                                                    />
                                                                    <span className="whitespace-nowrap">{subMenu.label}</span>
                                                                </Link>
                                                            </li>
                                                        );
                                                    })}
                                                </ul>
                                            )}
                                        </>
                                    )}
                                </li>
                            );
                        })}
                    </ul>
                </nav>
            </div>
            {/* Placeholder space, matching sidebar width */}
            <div className="w-20" />
        </>
    );
};

export { AppAsider };

import { zodResolver } from '@hookform/resolvers/zod';
import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { useNavigate } from 'react-router-dom';
import * as z from 'zod';

import { Button } from './ui/button';
import { Card, CardContent, CardFooter, CardHeader } from './ui/card';
import { Checkbox } from './ui/checkbox';
import {
    Form,
    FormControl,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from './ui/form';
import { Input } from './ui/input';

// Form validation schema
const formSchema = z.object({
    email: z.string().email({ message: 'Please enter a valid email address' }),
    password: z.string().min(6, { message: 'Password must be at least 6 characters' }),
    rememberMe: z.boolean().default(false),
});

export function LoginForm() {
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);

    // Initialize form
    const form = useForm<z.infer<typeof formSchema>>({
        resolver: zodResolver(formSchema),
        defaultValues: {
            email: '',
            password: '',
            rememberMe: false,
        },
    });

    // Form submission handler
    function onSubmit(values: z.infer<typeof formSchema>) {
        setIsLoading(true);

        // Simulate login request
        setTimeout(() => {
            console.log(values);
            setIsLoading(false);

            // Navigate to main page after successful login
            navigate('/');
        }, 1000);
    }

    // Handle Okta login
    function handleOktaLogin() {
        console.log('Logging in with Okta...');
    // Implement Okta login logic here
    }

    return (
        <Card className="w-full border-none bg-black text-white shadow-lg">
            <CardHeader className="space-y-2">

                {/* Okta Login Button */}
                <Button
                    type="button"
                    onClick={handleOktaLogin}
                    className="mt-2 w-full bg-white text-black hover:bg-gray-200"
                >
                    Login with Okta
                </Button>

                {/* Divider with "or" text */}
                <div className="authentication-divider relative my-4 text-center">
                    <div className="absolute inset-0 flex items-center">
                        <div className="w-full border-t border-gray-700" />
                    </div>
                    <span className="relative bg-black px-4 text-sm text-gray-500">or</span>
                </div>
            </CardHeader>

            <CardContent>
                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                        <FormField
                            control={form.control}
                            name="email"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-gray-300">Email</FormLabel>
                                    <FormControl>
                                        <Input
                                            placeholder="your.email@example.com"
                                            className="border-gray-800 bg-gray-900 text-white"
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                        <FormField
                            control={form.control}
                            name="password"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-gray-300">Password</FormLabel>
                                    <FormControl>
                                        <Input
                                            type="password"
                                            placeholder="Enter your password"
                                            className="border-gray-800 bg-gray-900 text-white"
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                        <div className="flex items-center justify-between">
                            <FormField
                                control={form.control}
                                name="rememberMe"
                                render={({ field }) => (
                                    <FormItem className="flex items-center space-x-2">
                                        <FormControl>
                                            <Checkbox
                                                checked={field.value}
                                                onCheckedChange={field.onChange}
                                                className="border-gray-600 data-[state=checked]:bg-white data-[state=checked]:text-black"
                                            />
                                        </FormControl>
                                        <FormLabel className="cursor-pointer text-sm text-gray-400">
                                            Remember me
                                        </FormLabel>
                                    </FormItem>
                                )}
                            />
                            <a href="#" className="text-sm text-blue-500 hover:text-blue-400">
                                Forgot password?
                            </a>
                        </div>
                        <Button
                            type="submit"
                            className="w-full bg-white text-black hover:bg-gray-200"
                            disabled={isLoading}
                        >
                            {isLoading ? 'Signing in...' : 'Sign in'}
                        </Button>
                    </form>
                </Form>
            </CardContent>
            <CardFooter className="flex justify-center border-t border-gray-800 pt-4">
                <p className="text-sm text-gray-400">
                    New to Content Hub?
                    {' '}
                    <a href="#" className="text-blue-500 hover:text-blue-400">Create an account</a>
                </p>
            </CardFooter>
        </Card>
    );
}

